import{_ as a,o as e,c as s,a2 as o}from"./chunks/framework.DbKnw1Aw.js";const u=JSON.parse('{"title":"订阅链接与短链","description":"","frontmatter":{},"headers":[],"relativePath":"guide/links.md","filePath":"guide/links.md","lastUpdated":1794385075000}'),d={name:"guide/links.md"};function l(i,t,r,n,c,p){return e(),s("div",null,[...t[0]||(t[0]=[o(`<h1 id="订阅链接与短链" tabindex="-1">订阅链接与短链 <a class="header-anchor" href="#订阅链接与短链" aria-label="Permalink to &quot;订阅链接与短链&quot;">​</a></h1><h2 id="三种订阅链接" tabindex="-1">三种订阅链接 <a class="header-anchor" href="#三种订阅链接" aria-label="Permalink to &quot;三种订阅链接&quot;">​</a></h2><table tabindex="0"><thead><tr><th>链接</th><th>内容</th><th>适用客户端</th></tr></thead><tbody><tr><td>Clash</td><td><code>/clash?…</code>，YAML 配置</td><td>Clash Verge、FlClash 等 mihomo 内核客户端</td></tr><tr><td>sing-box</td><td><code>/singbox?…</code>，JSON 配置</td><td>sing-box 及其图形客户端</td></tr><tr><td>Xray</td><td><code>/xray?…</code>，Base64 编码的节点列表</td><td>v2rayN 等支持 Base64 订阅的客户端</td></tr></tbody></table><p>链接的查询参数里包含节点、规则分类和自定义规则，客户端每次更新订阅时，Worker 都会按这些参数重新生成配置。参数格式见 <a href="./../api">API</a>。</p><div class="warning custom-block"><p class="custom-block-title">注意保密</p><p>节点信息直接写在链接参数里（短链则保存在你的 KV 中）。拿到链接的人就能拿到你的节点，不要公开分享。</p></div><h2 id="短链" tabindex="-1">短链 <a class="header-anchor" href="#短链" aria-label="Permalink to &quot;短链&quot;">​</a></h2><p>长链接不便于手动输入，也无法生成二维码。填一个短链路径（只允许字母、数字、<code>_</code> 和 <code>-</code>，留空则随机生成 7 位），点击&quot;生成短链&quot;，得到三条短链：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://&lt;你的域名&gt;/c/&lt;路径&gt;   # Clash</span></span>
<span class="line"><span>https://&lt;你的域名&gt;/b/&lt;路径&gt;   # sing-box</span></span>
<span class="line"><span>https://&lt;你的域名&gt;/x/&lt;路径&gt;   # Xray</span></span></code></pre></div><p>短链只保存长链接的查询参数，存储在 KV 中，不设过期时间。</p><h3 id="用同一路径更新" tabindex="-1">用同一路径更新 <a class="header-anchor" href="#用同一路径更新" aria-label="Permalink to &quot;用同一路径更新&quot;">​</a></h3><p>修改节点或规则后，界面会提示&quot;短链仍指向旧配置&quot;，按钮变为&quot;更新短链&quot;。点击后会用<strong>同一路径</strong>覆盖保存，客户端下次更新订阅就能拿到新配置，无需更换订阅地址。</p><div class="tip custom-block"><p class="custom-block-title">多设备共用</p><p>给所有设备订阅同一个固定路径（例如 <code>/c/my-sub</code>），以后只在页面上修改并更新短链即可。</p></div><p>短链路径没有归属概念，任何人用同一路径生成都会覆盖原有内容，建议使用不容易被猜到的路径。</p><h2 id="二维码" tabindex="-1">二维码 <a class="header-anchor" href="#二维码" aria-label="Permalink to &quot;二维码&quot;">​</a></h2><p>每条链接旁的二维码按钮会生成该链接的二维码。长链接通常超出二维码容量，请先生成短链。</p><h2 id="实时预览" tabindex="-1">实时预览 <a class="header-anchor" href="#实时预览" aria-label="Permalink to &quot;实时预览&quot;">​</a></h2><p>点击顶栏的预览按钮，右侧抽屉显示实际生成的配置文件：</p><ul><li>可在 Clash、sing-box、Xray 之间切换，Xray 显示 Base64 解码后的节点列表；</li><li>修改设置后，新出现的行会高亮并自动滚动到第一处变化；</li><li>顶部按钮可跳转到 <code>rules</code>、<code>proxy-groups</code>、<code>dns</code> 等段落，右上角可复制全文；</li><li>未填写节点时使用示例节点预览，方便先查看规则和分组结构。</li></ul><p>预览与订阅链接调用的是同一个接口，看到的就是客户端实际拿到的内容。抽屉收起时不会请求后端，重新打开时按最新设置生成一次。窄屏设备上，抽屉以浮层形式从右侧滑出。</p>`,19)])])}const b=a(d,[["render",l]]);export{u as __pageData,b as default};
